package com.pis.roi;
import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class RoiGeometryTest {
 private RoiGeometry.Point p(double x,double y){return new RoiGeometry.Point(x,y);}
 @Test void geometryRejectsNonFiniteLimitsDegenerateAndSelfIntersection(){for(var ps:List.of(List.of(p(Double.NaN,0)),List.of(p(Double.POSITIVE_INFINITY,0)),List.of(p(-1,0))))assertThatThrownBy(()->RoiGeometry.validate("POINT",ps,512,384)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->RoiGeometry.validate("POLYGON",List.of(p(0,0),p(10,10),p(0,10),p(10,0)),512,384)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->RoiGeometry.validate("RECTANGLE",List.of(p(0,0),p(0,10)),512,384)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->RoiGeometry.validate("POLYGON",java.util.stream.IntStream.range(0,33).mapToObj(i->p(i,i)).toList(),512,384)).isInstanceOf(IllegalArgumentException.class);}
 @Test void anisotropicCalibrationIsVersionBoundAndUnknownRemainsPixels(){var ps=List.of(p(0,0),p(10,20));RoiGeometry.validate("RECTANGLE",ps,512,384);var pixel=RoiGeometry.measure("RECTANGLE",ps,null,null,null);assertThat(pixel.area()).isEqualTo(200);assertThat(pixel.unit()).isEqualTo("px");var physical=RoiGeometry.measure("RECTANGLE",ps,.5,2.,7L);assertThat(physical.area()).isEqualTo(200);assertThat(physical.length()).isEqualTo(90);assertThat(physical.calibrationVersion()).isEqualTo(7);assertThat(physical.unit()).isEqualTo("SYNTHETIC_um");assertThatThrownBy(()->RoiGeometry.measure("RECTANGLE",ps,.5,null,7L)).isInstanceOf(IllegalArgumentException.class);}
 @Test void boundariesAndConcavePolygonAreValidWithoutChangingInput(){var ps=List.of(p(0,0),p(512,0),p(256,192),p(512,384),p(0,384));RoiGeometry.validate("POLYGON",ps,512,384);assertThat(RoiGeometry.measure("POLYGON",ps,null,null,null).area()).isGreaterThan(0);RoiGeometry.validate("POINT",List.of(p(512,384)),512,384);}
}
